/**
 * Dump state, suitable for debugging.
 *
 * @return Stringified form of this object.
 */
@Override
public String toString() {
    final StringBuilder buf = new StringBuilder();
    buf.append("[ Options: [ short ");
    buf.append(shortOpts.toString());
    buf.append(" ] [ long ");
    buf.append(longOpts);
    buf.append(" ]");
    return buf.toString();
}
